INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('wohnungsneubau-wien-fertigstellungen-minus-25-prozent-2026','Wohnungsneubau in Wien: Ein Viertel weniger fertige Wohnungen als 2022','In Wien werden deutlich weniger Wohnungen fertig als noch 2022. Eine Marktanalyse zeigt ein Minus von rund 25 Prozent – am 2. November diskutieren Branche, AK und Politik über Lösungen.','Der **Wohnungsneubau in Wien** hat in den vergangenen Jahren spürbar an Tempo verloren. Laut einer Auswertung des Immobiliendatenanbieters IMMOunited liegt die Zahl der fertiggestellten Wohneinheiten im Jahr 2026 um rund 25 Prozent unter dem Wert von 2022. Auch bei neu gestarteten Projekten gibt es ein Minus, allerdings ein deutlich kleineres von etwa 5,5 Prozent. Die Zahlen werden bei einer Podiumsdiskussion Anfang November in der Donaustadt vorgestellt, wie die Veranstalter am Dienstag per Aussendung bekannt gaben.

## Wohnungsneubau Wien: Was die neuen Zahlen zeigen

Die Analyse vergleicht das laufende Jahr mit 2022, also mit der Zeit vor dem starken Zinsanstieg und den gestiegenen Baukosten. Dass die Fertigstellungen viel stärker zurückgehen als die Projektstarts, hängt mit der Bauzeit zusammen: Wohnungen, die heute bezogen werden, wurden meist vor zwei bis drei Jahren begonnen – in einer Phase, in der viele Bauträger Vorhaben auf Eis gelegt haben.

Das Bild deckt sich mit dem Neubaubericht, den die Fachgruppe der Immobilien- und Vermögenstreuhänder der Wirtschaftskammer Wien vergangene Woche veröffentlicht hat. Demnach wurden 2025 in Wien rund 11.400 Wohnungen fertig. Für 2026 werden etwa 10.300 erwartet, für 2027 nur noch rund 9.650 – erstmals weniger als 10.000.

## Freifinanzierte Mietwohnungen besonders betroffen

Besonders stark trifft der Rückgang laut WKW-Bericht ein Segment:

- **Freifinanzierte Mietwohnungen:** rund 2.500 Fertigstellungen 2026, für 2027 sind nur knapp 500 angekündigt – ein Minus von etwa 80 Prozent.
- **Gemeinnützige Mietwohnungen:** etwa 2.740 im Jahr 2026, rund 2.680 im Jahr 2027.
- **Freifinanzierte Eigentumswohnungen:** rund 3.050 im Jahr 2026, 2027 sollen es knapp 4.000 werden.

Der Zuwachs bei Eigentum kann das Minus bei Miete damit nicht ausgleichen. Die Angebotspreise für neu gebaute Wohnungen lagen laut Wirtschaftskammer zuletzt rund 5,8 Prozent über dem Vorjahr. Zu beachten ist: Die Werte für 2027 sind Prognosen auf Basis bekannter Projekte und können sich noch verschieben.

## Diskussion über Wege zu mehr Wohnraum

Wie der Neubau wieder in Schwung kommen kann, ist Thema des zweiten „NIBRA Zukunftsgesprächs“ am **Montag, 2. November 2026, um 17 Uhr** in der Vienna Grand Gallery in der Dr.-Otto-Neurath-Gasse 5 im 22. Bezirk. Initiiert wurde die Reihe vom Wiener Aufzugsunternehmer Nikolaus Brada, gemeinsam mit IMMOunited-COO Valentin Bauer, der die Marktanalyse präsentiert.

Am Podium sitzen Vertreterinnen und Vertreter mit teils sehr unterschiedlichen Interessen:

1. Andreas Köttl, Präsident der Vereinigung Österreichischer Projektentwickler (VÖPE)
2. Clemens Berger, Mietrechtsexperte der Arbeiterkammer Wien
3. Benedikt Stockert, Rechtsanwalt (FSM Rechtsanwälte)
4. Karina Schunker, Geschäftsführerin von EHL Wohnen
5. Heidi Sequenz, Wiener Gemeinderätin und Sprecherin für Stadtplanung

Moderiert wird von VÖPE-Geschäftsführer Alexander Pawkowicz. Im Mittelpunkt stehen Investitionsbedingungen, Planungssicherheit sowie die Frage, welches Potenzial Neubau, Nachverdichtung und die Nutzung bestehender Gebäude haben.

## Was das für Wohnungssuchende bedeutet

Weniger neue Wohnungen bedeuten mittelfristig ein knapperes Angebot, vor allem bei frei vermieteten Neubauwohnungen. Die Branche fordert seit Monaten schnellere Genehmigungsverfahren, stabile Rahmenbedingungen und bessere Finanzierungsmöglichkeiten. Mieterschützer betonen dagegen die Rolle des geförderten und gemeinnützigen Wohnbaus für leistbares Wohnen. Wer in den kommenden Jahren in Wien eine Wohnung sucht, sollte daher auch den Bestand und den geförderten Sektor im Blick behalten – etwa über das Wohnservice Wien.','bauen-wohnen','Immobilien','wien','news','Presseinfo Redaktion','/assets/img/artikel/wohnungsneubau-wien-fertigstellungen-minus-25-prozent-2026.webp','OTS / Social City Wien (NIBRA Zukunftsgespräch)','https://www.ots.at/presseaussendung/OTS_20261027_OTS0012/aviso-wie-kommt-wiens-wohnungsneubau-wieder-in-gang','published','2026-10-27T08:55:00.000Z','2026-10-27T08:47:19.152Z','Wohnungsneubau Wien: 25 % weniger Fertigstellungen','Wohnungsneubau in Wien: Fertigstellungen liegen rund 25 % unter 2022. Was die Zahlen zeigen und wer am 2. November über Auswege diskutiert.','Wohnungsneubau Wien','["Wohnungsneubau Wien","Neubau Wohnungen Wien","Wohnraum Wien","Wohnungsmarkt Wien 2026","Mietwohnungen Wien 2027","Fertigstellungen Wohnungen Wien","leistbares Wohnen Wien","NIBRA Zukunftsgespräch Wohnraum"]','Wohnungsneubau Wien: Halbfertiger Wohnbau mit Gerüst und Kran an einem Herbstmorgen','Residential construction site in Vienna outskirts on an overcast autumn morning, half-finished concrete apartment building with scaffolding and a single idle tower crane, empty site, puddles, Viennese suburban apartment blocks in background, no people, no text, no logos, no readable signs','[{"q":"Wie stark ist der Wohnungsneubau in Wien zurückgegangen?","a":"Laut IMMOunited-Analyse werden 2026 rund 25 Prozent weniger Wohnungen fertig als 2022; Projektstarts liegen etwa 5,5 Prozent darunter."},{"q":"Wie viele Wohnungen werden 2027 in Wien fertig?","a":"Der Neubaubericht der Wirtschaftskammer Wien erwartet rund 9.650 Fertigstellungen, davon nur knapp 500 freifinanzierte Mietwohnungen."},{"q":"Wann findet das NIBRA Zukunftsgespräch statt?","a":"Am Montag, 2. November 2026, um 17 Uhr in der Vienna Grand Gallery im 22. Bezirk."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
